using UnityEngine;
using UnityEditor;
public static class CompressForestSky {
public static object Main(){var path="Assets/Game/Art/Environment/SpruitSunrise/spruit_sunrise_4k.hdr";var texture=AssetDatabase.LoadAssetAtPath<Cubemap>(path);long before=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(texture);int width=texture.width;var importer=(TextureImporter)AssetImporter.GetAtPath(path);var settings=importer.GetDefaultPlatformTextureSettings();settings.format=TextureImporterFormat.BC6H;settings.textureCompression=TextureImporterCompression.CompressedHQ;settings.compressionQuality=100;importer.SetPlatformTextureSettings(settings);importer.SaveAndReimport();texture=AssetDatabase.LoadAssetAtPath<Cubemap>(path);var result=new {beforeBytes=before,afterBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(texture),oldWidth=width,width=texture.width,format=texture.format.ToString()};System.IO.File.WriteAllText("docs/reports/sky-memory.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
